package br.com.erombox.nativeapp;

import android.app.*;
import android.os.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.content.*;
import android.media.MediaPlayer;
import android.text.InputType;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MainActivity extends Activity {
  private final ExecutorService io = Executors.newSingleThreadExecutor();
  private String baseUrl="", anonKey="", accessToken="";
  private LinearLayout root, content;
  private EditText emailField, passwordField;
  private MediaPlayer player;
  private final int bg=Color.rgb(10,10,12), panel=Color.rgb(26,26,30), white=Color.WHITE, muted=Color.rgb(170,170,180), accent=Color.rgb(186,146,255);
  @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);getWindow().getDecorView().setSystemUiVisibility(0); baseUrl=getString(getResources().getIdentifier("supabase_url","string",getPackageName())); anonKey=getString(getResources().getIdentifier("supabase_anon_key","string",getPackageName())); accessToken=getPreferences(0).getString("token",""); showHomeOrLogin();}
  private void shell(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(24),dp(22),dp(18));root.setBackgroundColor(bg);setContentView(root); ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(1);content.setPadding(0,0,0,dp(20));sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
  private int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
  private TextView text(String s,int size,boolean bold,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(0,dp(7),0,dp(7));return t;}
  private void showHomeOrLogin(){if(accessToken.isEmpty())showLogin();else loadLibrary();}
  private void showLogin(){shell();content.addView(text("EROM BOX",32,true,white));content.addView(text("Sua música. Do seu jeito.",16,false,muted));space(32);content.addView(text("Entrar na sua conta",22,true,white));emailField=field("E-mail",false);passwordField=field("Senha",true);content.addView(emailField);content.addView(passwordField);space(12);Button login=button("Entrar");content.addView(login);login.setOnClickListener(v->auth(false));Button signup=button("Criar conta");content.addView(signup);signup.setOnClickListener(v->auth(true));}
  private EditText field(String hint,boolean pass){EditText e=new EditText(this);e.setSingleLine(true);e.setTextColor(white);e.setHintTextColor(muted);e.setHint(hint);e.setPadding(dp(14),dp(12),dp(14),dp(12));e.setBackgroundColor(panel);e.setInputType(pass?129:33);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(54));lp.bottomMargin=dp(12);e.setLayoutParams(lp);return e;}
  private Button button(String label){Button b=new Button(this);b.setText(label);b.setTextColor(bg);b.setAllCaps(false);b.setTextSize(16);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(accent));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(52));lp.bottomMargin=dp(10);b.setLayoutParams(lp);return b;}
  private void space(int h){View v=new View(this);content.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
  private void auth(boolean signup){String email=emailField.getText().toString().trim(),pass=passwordField.getText().toString();if(email.isEmpty()||pass.length()<6){toast("Informe e-mail e senha (mínimo 6 caracteres).");return;}hideKeyboard();progress("Conectando…");io.execute(()->{try{String path=signup?"/auth/v1/signup":"/auth/v1/token?grant_type=password";JSONObject body=new JSONObject().put("email",email).put("password",pass);JSONObject res=request("POST",path,body,null);String token=res.optString("access_token","");runOnUiThread(()->{if(!token.isEmpty()){accessToken=token;getPreferences(0).edit().putString("token",token).apply();loadLibrary();}else if(signup){dismiss();toast("Cadastro enviado. Confira seu e-mail para confirmar a conta.");}else{dismiss();toast("Não foi possível entrar. Confira os dados.");}});}catch(Exception e){runOnUiThread(()->{dismiss();toast("Falha de conexão: "+e.getMessage());});}});}
  private void loadLibrary(){shell();content.addView(text("EROM BOX",28,true,white));content.addView(text("SUA BIBLIOTECA",12,true,accent));content.addView(text("Carregando suas músicas…",15,false,muted));Button refresh=button("Atualizar biblioteca");content.addView(refresh);refresh.setOnClickListener(v->loadLibrary());Button logout=button("Sair da conta");content.addView(logout);logout.setOnClickListener(v->{accessToken="";getPreferences(0).edit().remove("token").apply();showLogin();});io.execute(()->{try{JSONArray rows=requestArray("GET","/rest/v1/songs?select=*&limit=100",null);runOnUiThread(()->renderSongs(rows));}catch(Exception e){runOnUiThread(()->{content.removeAllViews();content.addView(text("EROM BOX",28,true,white));content.addView(text("Não foi possível carregar a biblioteca.",18,true,white));content.addView(text("O login foi aceito, mas a consulta de músicas precisa corresponder à tabela configurada no seu servidor.",14,false,muted));content.addView(text(e.getMessage(),12,false,muted));Button retry=button("Tentar novamente");content.addView(retry);retry.setOnClickListener(v->loadLibrary());});}});}
  private void renderSongs(JSONArray rows){content.removeAllViews();content.addView(text("EROM BOX",28,true,white));content.addView(text("SUA BIBLIOTECA  •  "+rows.length()+" FAIXAS",12,true,accent));if(rows.length()==0)content.addView(text("Ainda não há músicas nesta biblioteca.",16,false,muted));for(int i=0;i<rows.length();i++){JSONObject song=rows.optJSONObject(i);if(song==null)continue;String title=first(song,"title","name","song_name","track_name");String artist=first(song,"artist","artist_name","author");String url=first(song,"audio_url","url","file_url","stream_url","storage_url");LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(14),dp(10),dp(14),dp(10));card.setBackgroundColor(panel);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(9);content.addView(card,cp);card.addView(text(title,16,true,white));if(!artist.isEmpty())card.addView(text(artist,13,false,muted));if(!url.isEmpty()){Button play=button("▶  Reproduzir");card.addView(play);play.setOnClickListener(v->play(url,title));}}Button logout=button("Sair da conta");content.addView(logout);logout.setOnClickListener(v->{accessToken="";getPreferences(0).edit().remove("token").apply();showLogin();});}
  private String first(JSONObject o,String... keys){for(String k:keys){String s=o.optString(k,"");if(!s.isEmpty()&&!s.equals("null"))return s;}return "";}
  private void play(String url,String title){try{if(player!=null){player.release();player=null;}player=new MediaPlayer();player.setDataSource(url);player.setOnPreparedListener(mp->{mp.start();toast("Reproduzindo: "+title);});player.setOnErrorListener((mp,w,e)->{toast("Não foi possível reproduzir este arquivo.");return true;});player.prepareAsync();}catch(Exception e){toast("Erro ao abrir áudio.");}}
  private JSONObject request(String method,String path,JSONObject body,String token)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(baseUrl+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("apikey",anonKey);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Accept","application/json");if(token!=null)c.setRequestProperty("Authorization","Bearer "+token);else if(!accessToken.isEmpty())c.setRequestProperty("Authorization","Bearer "+accessToken);if(body!=null){c.setDoOutput(true);try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();InputStream in=code<400?c.getInputStream():c.getErrorStream();String s=read(in);if(code>=400)throw new IOException("Servidor respondeu "+code+": "+s);return s.trim().startsWith("{")?new JSONObject(s):new JSONObject();}
  private JSONArray requestArray(String method,String path,JSONObject body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(baseUrl+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("apikey",anonKey);c.setRequestProperty("Authorization","Bearer "+accessToken);c.setRequestProperty("Accept","application/json");if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();String s=read(code<400?c.getInputStream():c.getErrorStream());if(code>=400)throw new IOException("Servidor respondeu "+code+": "+s);return new JSONArray(s);}
  private String read(InputStream in)throws Exception{if(in==null)return "";try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){StringBuilder b=new StringBuilder();String l;while((l=r.readLine())!=null)b.append(l);return b.toString();}}
  private void progress(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
  private void dismiss(){}
  private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
  private void hideKeyboard(){try{((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);}catch(Exception ignored){}}
  @Override protected void onDestroy(){if(player!=null){player.release();player=null;}io.shutdownNow();super.onDestroy();}
}
